import os, re

pat = re.compile(r'^[0-9A-Z]{17}$')
files = []
for root, _, names in os.walk('/app/varsea'):
    for n in names:
        files.append(os.path.join(root, n))

out = []
for path in files:
    with open(path, 'rb') as f:
        data = f.read()
    L = len(data)
    for k in range(1, 65):
        # use known ends to get key bytes for positions mod k
        kb = {}
        ok = True
        for off, ch in enumerate(b'8XD'):
            if off % k in kb and kb[off % k] != ch:
                ok = False; break
            kb[off % k] = ch
        if not ok: continue
        for off, ch in enumerate(b'W54'):
            p = L - 3 + off
            if p % k in kb and kb[p % k] != ch:
                ok = False; break
            kb[p % k] = ch
        if not ok: continue
        if len(kb) != k: continue
        cand = bytearray()
        for i in range(3, L - 3):
            b = data[i] ^ kb[i % k]
            cand.append(b)
        s = bytes(cand).decode('ascii', 'replace')
        if pat.match(s):
            out.append('8XD' + s + 'W54')

for p in sorted(set(out)):
    print(p)
